begin;
create table public.community_moderators(user_id uuid primary key references auth.users(id) on delete cascade);
alter table public.community_moderators enable row level security;
revoke all on public.community_moderators from anon,authenticated;
create function public.community_is_moderator() returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.community_moderators where user_id=auth.uid()); $$;
revoke all on function public.community_is_moderator() from public;
grant execute on function public.community_is_moderator() to anon,authenticated;
create table public.community_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null default auth.uid() references auth.users(id) on delete cascade,display_name text not null check(length(display_name) between 1 and 60),title text not null check(length(title) between 3 and 120),destination text not null check(length(destination) between 2 and 100),ages text not null check(length(ages)<=100),days integer not null check(days between 1 and 60),body text not null check(length(body) between 30 and 10000),status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now());
alter table public.community_posts enable row level security;
grant select,insert,update,delete on public.community_posts to authenticated;
grant select on public.community_posts to anon;
create policy "Read published or own" on public.community_posts for select using(status='approved' or author_id=auth.uid() or public.community_is_moderator());
create policy "Submit pending own" on public.community_posts for insert to authenticated with check(author_id=auth.uid() and status='pending');
create policy "Edit own or moderate" on public.community_posts for update to authenticated using(author_id=auth.uid() or public.community_is_moderator()) with check(author_id=auth.uid() or public.community_is_moderator());
create policy "Withdraw own or moderate" on public.community_posts for delete to authenticated using(author_id=auth.uid() or public.community_is_moderator());
create function public.community_review_edits() returns trigger language plpgsql set search_path = '' as $$ begin if new.author_id<>old.author_id or new.created_at<>old.created_at then raise exception 'Immutable author and date'; end if; if not public.community_is_moderator() then new.status:='pending'; end if; return new; end; $$;
create trigger community_edits_review before update on public.community_posts for each row execute function public.community_review_edits();
create table public.community_votes(post_id uuid references public.community_posts(id) on delete cascade,user_id uuid default auth.uid() references auth.users(id) on delete cascade,primary key(post_id,user_id));
create table public.community_saves(post_id uuid references public.community_posts(id) on delete cascade,user_id uuid default auth.uid() references auth.users(id) on delete cascade,primary key(post_id,user_id));
alter table public.community_votes enable row level security;
alter table public.community_saves enable row level security;
grant select,insert,delete on public.community_votes,public.community_saves to authenticated;
create policy "Read own votes" on public.community_votes for select to authenticated using(user_id=auth.uid());
create policy "Vote published" on public.community_votes for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.community_posts p where p.id=post_id and p.status='approved'));
create policy "Remove own vote" on public.community_votes for delete to authenticated using(user_id=auth.uid());
create policy "Read own saves" on public.community_saves for select to authenticated using(user_id=auth.uid());
create policy "Save published" on public.community_saves for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.community_posts p where p.id=post_id and p.status='approved'));
create policy "Remove own save" on public.community_saves for delete to authenticated using(user_id=auth.uid());
create table public.community_reports(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.community_posts(id) on delete cascade,user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,reason text not null check(length(reason) between 5 and 1000),created_at timestamptz not null default now(),unique(post_id,user_id));
alter table public.community_reports enable row level security;
grant select,insert,delete on public.community_reports to authenticated;
create policy "Report published" on public.community_reports for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.community_posts p where p.id=post_id and p.status='approved'));
create policy "Read reports as moderator" on public.community_reports for select to authenticated using(public.community_is_moderator());
create policy "Resolve reports as moderator" on public.community_reports for delete to authenticated using(public.community_is_moderator());
create function public.community_feed() returns table(id uuid,display_name text,title text,destination text,ages text,days integer,body text,created_at timestamptz,helpful bigint) language sql stable security definer set search_path = '' as $$ select p.id,p.display_name,p.title,p.destination,p.ages,p.days,p.body,p.created_at,(select count(*) from public.community_votes v where v.post_id=p.id) from public.community_posts p where p.status='approved' order by p.created_at desc limit 200; $$;
revoke all on function public.community_feed() from public;
grant execute on function public.community_feed() to anon,authenticated;
commit;
